function SecurityPage({ session }: { session: Session }) {
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [notice, setNotice] = useState<{
    tone: 'error' | 'success';
    text: string;
  } | null>(null);
  const [loading, setLoading] = useState(false);

  async function submit(event: FormEvent) {
    event.preventDefault();
    if (newPassword !== confirm)
      return setNotice({
        tone: 'error',
        text: 'The new passwords do not match.',
      });
    if (!strongPassword(newPassword))
      return setNotice({
        tone: 'error',
        text: 'Use at least 10 characters with uppercase, lowercase, a number, and a symbol.',
      });
    setLoading(true);
    setNotice(null);
    try {
      const response = await portalApi.changePassword(
        session.token,
        currentPassword,
        newPassword,
      );
      setNotice({ tone: 'success', text: response.message });
      setCurrentPassword('');
      setNewPassword('');
      setConfirm('');
    } catch (caught) {
      setNotice({ tone: 'error', text: errorMessage(caught) });
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="page-stack narrow-page">
      <PageTitle
        eyebrow="Account"
        title="Security"
        copy="Keep your portal credentials private and up to date."
      />
      <section className="card security-card">
        <span className="security-icon">
          <KeyRound size={25} />
        </span>
        <div>
          <h2>Change password</h2>
          <p className="muted">
            Changing your password revokes your other active portal sessions.
          </p>
        </div>
        <form className="form-stack" onSubmit={submit}>
          <Field label="Current password">
            <input
              type="password"
              value={currentPassword}
              onChange={(event) => setCurrentPassword(event.target.value)}
              required
            />
          </Field>
          <Field label="New password">
            <input
              type="password"
              value={newPassword}
              onChange={(event) => setNewPassword(event.target.value)}
              required
            />
          </Field>
          <Field label="Confirm new password">
            <input
              type="password"
              value={confirm}
              onChange={(event) => setConfirm(event.target.value)}
              required
            />
          </Field>
          <PasswordRules password={newPassword} />
          {notice && <Alert tone={notice.tone}>{notice.text}</Alert>}
          <button className="button button-primary" disabled={loading}>
            {loading ? 'Updating…' : 'Update password'}
          </button>
        </form>
      </section>
      <section className="card privacy-card">
        <ShieldCheck size={24} />
        <div>
          <h3>Protect your health information</h3>
          <p>
            Never share your password. Always sign out when using a shared
            device. Hospital staff will never ask for your password.
          </p>
        </div>
      </section>
    </div>
  );
}

