function PasswordRules({ password }: { password: string }) {
  const rules = [
    ['10+ characters', password.length >= 10],
    ['Upper and lowercase', /[A-Z]/.test(password) && /[a-z]/.test(password)],
    ['Number and symbol', /\d/.test(password) && /[^A-Za-z0-9]/.test(password)],
  ] as const;
  return (
    <div className="password-rules">
      {rules.map(([label, valid]) => (
        <span className={valid ? 'rule-valid' : ''} key={label}>
          <i>{valid ? '✓' : '·'}</i>
          {label}
        </span>
      ))}
    </div>
  );
}

function useLoad<T>(
  loader: () => Promise<T>,
  dependencies: ReadonlyArray<unknown>,
) {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [version, setVersion] = useState(0);
  const reload = useCallback(() => setVersion((value) => value + 1), []);

  useEffect(() => {
    let active = true;
    setLoading(true);
    setError('');
    loader()
      .then((value) => {
        if (active) setData(value);
      })
      .catch((caught) => {
        if (active) setError(errorMessage(caught));
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
    // The caller supplies the values that identify this request.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [...dependencies, version]);

  return { data, loading, error, reload };
}

function errorMessage(error: unknown) {
  if (error instanceof ApiError && error.status === 401)
    return 'Your session has expired or the credentials are incorrect.';
  return error instanceof Error
    ? error.message
    : 'Something went wrong. Please try again.';
}

function strongPassword(value: string) {
  return (
    value.length >= 10 &&
    /[A-Z]/.test(value) &&
    /[a-z]/.test(value) &&
    /\d/.test(value) &&
    /[^A-Za-z0-9]/.test(value)
  );
}
function initials(name: string) {
  return (
    name
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0])
      .join('')
      .toUpperCase() || 'PT'
  );
}
function firstName(name: string) {
  return name.trim().split(/\s+/)[0] || 'Patient';
}
function money(value: number) {
  return new Intl.NumberFormat('en-PH', {
    style: 'currency',
    currency: 'PHP',
  }).format(value || 0);
}
function dateValue(value?: string | null) {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}
function shortDate(value?: string | null) {
  const date = dateValue(value);
  return date
    ? new Intl.DateTimeFormat('en-PH', {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
      }).format(date)
    : '—';
}
function longDate(value?: string | null) {
  const date = dateValue(value);
  return date
    ? new Intl.DateTimeFormat('en-PH', {
        month: 'long',
        day: 'numeric',
        year: 'numeric',
      }).format(date)
    : 'Not recorded';
}
function dateTime(value?: string | null) {
  const date = dateValue(value);
  return date
    ? new Intl.DateTimeFormat('en-PH', {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
        hour: 'numeric',
        minute: '2-digit',
      }).format(date)
    : '—';
}
function day(value: string) {
  return dateValue(value)?.getDate() || '—';
}
function month(value: string) {
  const date = dateValue(value);
  return date
    ? new Intl.DateTimeFormat('en-PH', { month: 'short' })
        .format(date)
        .toUpperCase()
    : '—';
}
function year(value: string) {
  return dateValue(value)?.getFullYear() || '—';
}
function friendlyKey(value: string) {
  return value.replace(/([a-z])([A-Z])/g, '$1 $2').replace(/_/g, ' ');
}
function plainValue(value: unknown) {
  if (value === null || value === undefined) return '';
  const raw = String(value);
  if (!raw.includes('<')) return raw;
  const document = new DOMParser().parseFromString(raw, 'text/html');
  return document.body.textContent?.trim() || '';
}
function visibleEntries(record: Record<string, unknown>) {
  const hidden = new Set([
    'Id',
    'CaseId',
    'PatientId',
    'AddedBy',
    'AddedDate',
    'UpdatedBy',
    'UpdatedDate',
    'DeletedBy',
    'DeletedDate',
    'ReqPhysicianId',
    'PathologistId',
    'MedTechId',
    'MedTech1Id',
    'RadTechId',
    'RadiologistId',
  ]);
  const priority = new Set([
    'ExaminationNo',
    'ExamTitle',
    'DatePerform',
    'ReqPhysician',
    'Radiologist',
    'Pathologist',
    'Findings',
    'Impression',
    'Remarks',
    'Interpretation',
  ]);
  return Object.entries(record)
    .filter(
      ([key, value]) =>
        !hidden.has(key) && priority.has(key) && plainValue(value),
    )
    .slice(0, 10);
}

export default App;
